fn validate_themes(content: &str) -> Result<(), String> {
    // Need to parse toml and validate colors/modifiers
    // For now, try to parse as toml::Value, then validate known fields
    // If toml parse fails, return toml error string
    let val: Result<toml::Value, _> = toml::from_str(content);
    match val {
        Ok(v) => {
            // Validate colors and modifiers in known structure
            // Walk through tables and check fg/bg/error/warning/info/question as colors, modifiers as modifiers
            if let Err(e) = validate_themes_value(&v) {
                return Err(e);
            }
            Ok(())
        }
        Err(e) => Err(e.to_string()),
    }
}

fn validate_themes_value(v: &toml::Value) -> Result<(), String> {
    // Check top-level tables: general, journals_list, editor, msgbox
    // For msgbox: error, warning, info, question must be colors
    // For others: each sub-table has fg, bg, modifiers, underline_color?
    // We need to replicate error messages: for invalid color, error is "Failed to parse Colors" with line/col?
    // But our simple validation returning string won't have line/col. Need to use serde deserialization with custom Color type that fails with that message and preserves line/col via toml error.
    // Simpler: define structs with custom deserializers for Color and Modifiers that error with those messages, then toml::from_str::<Themes>(content) will produce proper line/col errors.
    // Let's do that.
    match toml::from_str::<ThemesCheck>( &toml::to_string(v).unwrap_or_default() ) {
        Ok(_) => Ok(()),
        Err(e) => Err(e.to_string()),
    }
}

