fn absolutize_path(p: &Path) -> PathBuf {
    let joined = if p.is_absolute() {
        p.to_path_buf()
    } else {
        std::env::current_dir().unwrap_or(PathBuf::from(".")).join(p)
    };
    normalize_path(&joined)
}

fn normalize_path(p: &Path) -> PathBuf {
    use std::path::Component;
    let mut out: Vec<String> = Vec::new();
    let is_abs = p.is_absolute();
    for comp in p.components() {
        match comp {
            Component::Prefix(prefix) => {
                out.push(prefix.as_os_str().to_string_lossy().to_string());
            }
            Component::RootDir => {
                // handled by is_abs
            }
            Component::CurDir => {
                // skip
            }
            Component::ParentDir => {
                if let Some(last) = out.pop() {
                    // Don't pop prefix?
                    // If last is prefix, push back?
                    // Simple: if out empty or last is prefix, keep ..?
                    // For absolute, just pop if possible
                    if last.contains(":") {
                        out.push(last);
                        out.push("..".to_string());
                    }
                } else {
                    // for relative, keep .., but we are absolute, so ignore (can't go above root)
                    if !is_abs {
                        out.push("..".to_string());
                    }
                }
            }
            Component::Normal(s) => {
                out.push(s.to_string_lossy().to_string());
            }
        }
    }
    let mut res = String::new();
    if is_abs {
        res.push('/');
    }
    // Handle prefix (windows) - ignore
    res.push_str(&out.join("/"));
    if res.is_empty() {
        res = "/".to_string();
    }
    PathBuf::from(res)
}

