}

fn de_color_opt<'de, D>(deserializer: D) -> Result<Option<String>, D::Error>
where D: serde::Deserializer<'de> {
    use serde::Deserialize;
    let opt: Option<String> = Option::deserialize(deserializer)?;
    if let Some(s) = opt {
        if !is_valid_color(&s) {
            return Err(serde::de::Error::custom("Failed to parse Colors"));
        }
        Ok(Some(s))
    } else {
        Ok(None)
    }
}

fn de_modifiers_opt<'de, D>(deserializer: D) -> Result<Option<String>, D::Error>
where D: serde::Deserializer<'de> {
    use serde::Deserialize;
    let opt: Option<String> = Option::deserialize(deserializer)?;
    if let Some(s) = opt {
        if let Err(flag) = validate_modifiers(&s) {
            return Err(serde::de::Error::custom(format!("unrecognized named flag `{}`", flag)));
        }
        Ok(Some(s))
    } else {
        Ok(None)
    }
}

fn is_valid_color(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    if s.starts_with('#') {
        if s.len() != 7 {
            return false;
        }
        return s[1..].chars().all(|c| c.is_ascii_hexdigit());
    }
    let lower = s.to_ascii_lowercase();
    matches!(lower.as_str(), "black" | "red" | "green" | "yellow" | "blue" | "magenta" | "cyan" | "gray" | "grey" | "darkgray" | "darkgrey" | "lightred" | "lightgreen" | "lightyellow" | "lightblue" | "lightmagenta" | "lightcyan" | "white" | "reset" | "lightgray" | "lightgrey")
}

fn validate_modifiers(s: &str) -> Result<(), String> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Ok(());
    }
    for part in trimmed.split('|') {
        let flag = part.trim();
        if flag.is_empty() {
            continue;
        }
        match flag {
            "BOLD" | "DIM" | "ITALIC" | "UNDERLINED" | "SLOW_BLINK" | "RAPID_BLINK" | "REVERSED" | "HIDDEN" | "CROSSED_OUT" => {}
            _ => return Err(flag.to_string()),
        }
    }
    Ok(())
}

