        let c_desc = CString::new(desc).unwrap();
        unsafe { ffi::sqlite3_bind_text(st, 2, c_desc.as_ptr(), -1, None) };
        unsafe { ffi::sqlite3_bind_blob(st, 3, bytes.as_ptr() as *const c_void, bytes.len() as c_int, None) };
        // execution_time: use 100000 + random-ish? Use 100000
        unsafe { ffi::sqlite3_bind_int64(st, 4, 100000) };
        let step = unsafe { ffi::sqlite3_step(st) };
        unsafe { ffi::sqlite3_finalize(st) };
        if step != ffi::SQLITE_DONE {
            return Err(sqlite_err(db));
        }
        // Keep bytes alive until after step? Already stepped, ok.
    }
    Ok(())
