fn hex_to_bytes(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    for i in (0..chars.len()).step_by(2) {
        let h = chars[i].to_digit(16).unwrap_or(0);
        let l = chars[i+1].to_digit(16).unwrap_or(0);
        out.push((h*16 + l) as u8);
    }
    out
}

