        if let Some(p) = entry.priority {
            unsafe { ffi::sqlite3_bind_int(stmt, 4, p as c_int) };
        } else {
            unsafe { ffi::sqlite3_bind_null(stmt, 4) };
        }
        unsafe { ffi::sqlite3_bind_int(stmt, 5, entry.id as c_int) };
        let step = unsafe { ffi::sqlite3_step(stmt) };
        unsafe { ffi::sqlite3_finalize(stmt) };
        if step != ffi::SQLITE_DONE { return Err(sqlite_err(db)); }
        // Delete old tags, insert new
        let del = format!("DELETE FROM tags WHERE entry_id = {}", entry.id);
        exec_sql(db, &del)?;
        for tag in &entry.tags {
            let sql2 = "INSERT OR IGNORE INTO tags (entry_id, tag) VALUES (?, ?)";
            let c_sql2 = CString::new(sql2).unwrap();
            let mut st2: *mut c_void = ptr::null_mut();
            let rc2 = unsafe { ffi::sqlite3_prepare_v2(db, c_sql2.as_ptr(), -1, &mut st2, ptr::null_mut()) };
            if rc2 != ffi::SQLITE_OK { return Err(sqlite_err(db)); }
            unsafe { ffi::sqlite3_bind_int(st2, 1, entry.id as c_int) };
            let c_tag = CString::new(tag.as_bytes()).unwrap();
            unsafe { ffi::sqlite3_bind_text(st2, 2, c_tag.as_ptr(), -1, None) };
            let s = unsafe { ffi::sqlite3_step(st2) };
            unsafe { ffi::sqlite3_finalize(st2) };
            if s != ffi::SQLITE_DONE { return Err(sqlite_err(db)); }
        }
        Ok(())
    })();
    unsafe { ffi::sqlite3_close(db) };
    res
}

pub fn delete_sqlite(path: &Path, id: u32) -> Result<()> {
    let db = open_db(path)?;
    let res: Result<()> = (|| {
        ensure_schema(db)?;
        // Delete tags first (foreign key cascade may not be enabled, so manual)
        let del_tags = format!("DELETE FROM tags WHERE entry_id = {}", id);
        exec_sql(db, &del_tags)?;
        let del = format!("DELETE FROM entries WHERE id = {}", id);
        exec_sql(db, &del)?;
        Ok(())
    })();
    unsafe { ffi::sqlite3_close(db) };
    res
}

pub fn assign_priority_sqlite(path: &Path, prio: u32) -> Result<()> {
    let db = open_db(path)?;
    let res: Result<()> = (|| {
        ensure_schema(db)?;
        let sql = format!("UPDATE entries SET priority = {} WHERE priority IS NULL", prio);
        exec_sql(db, &sql)?;
        Ok(())
    })();
    unsafe { ffi::sqlite3_close(db) };
    res
}
