        // Sort
        let criteria = self.sorter_criteria.clone();
        let order = self.sorter_order.clone();
        indices.sort_by(|&a, &b| {
            let ea = &self.entries[a];
            let eb = &self.entries[b];
            for crit in &criteria {
                let ord = match crit.as_str() {
                    "Date" => ea.date.cmp(&eb.date),
                    "Priority" => match (&ea.priority, &eb.priority) {
                        (None, None) => std::cmp::Ordering::Equal,
                        (None, Some(_)) => std::cmp::Ordering::Less,
                        (Some(_), None) => std::cmp::Ordering::Greater,
                        (Some(x), Some(y)) => x.cmp(y),
                    },
                    "Title" => ea.title.cmp(&eb.title),
                    _ => std::cmp::Ordering::Equal,
                };
                if ord != std::cmp::Ordering::Equal {
                    if order == "Descending" {
                        return ord.reverse();
                    } else {
                        return ord;
                    }
                }
            }
            // Tie-breaker by id? Original likely stable? Use id.
            ea.id.cmp(&eb.id)
        });
