        let mut checks: Vec<bool> = Vec::new();
        if !self.filter.title.is_empty() {
            checks.push(e.title.to_lowercase().contains(&self.filter.title.to_lowercase()));
        }
        if !self.filter.content.is_empty() {
            checks.push(e.content.to_lowercase().contains(&self.filter.content.to_lowercase()));
        }
        if !self.filter.priority.is_empty() {
            // Priority filter: how does it work? Possibly exact match? Or contains? Let's assume exact match of priority number string?
            // If entry priority None, then false unless filter is empty? But filter not empty here.
            if let Some(p) = e.priority {
                checks.push(p.to_string() == self.filter.priority);
            } else {
                checks.push(false);
            }
        }
        if !self.filter.selected_tags.is_empty() {
            // If NO_TAGS selected? Tags list includes "NO_TAGS (Entries with no tags)"? How to handle?
            // For now: check if entry has any of selected tags, or if NO_TAGS selected and entry has no tags.
            let mut tag_match = false;
            for t in &self.filter.selected_tags {
                if t == "NO_TAGS" {
                    if e.tags.is_empty() {
                        tag_match = true;
                        break;
                    }
                } else if e.tags.contains(t) {
                    tag_match = true;
                    break;
                }
            }
            checks.push(tag_match);
        }
        if checks.is_empty() {
            return true;
        }
        if self.filter.matching_all {
            checks.iter().all(|&x| x)
        } else {
            checks.iter().any(|&x| x)
        }
    }

