        self.view.get(self.selected).map(|&i| &self.entries[i])
    }

    fn selected_entry_mut(&mut self) -> Option<&mut Entry> {
        if let Some(&i) = self.view.get(self.selected) {
            self.entries.get_mut(i)
        } else {
            None
        }
    }

