    fn calc_footer_height(&self, width: u16, text: &str) -> u16 {
        if width == 0 { return 1; }
        // Simulate ratatui Paragraph wrap: words wrap? Or char wrap? Ratatui Wrap with trim false wraps at width, breaking words? Actually it wraps by words? Need to check.
        // For footer, text contains " | " separators, no newlines. Wrapping is by width, breaking at spaces? Let's implement simple: split into words? Or just char count?
        // Observed: at 80 width, footer "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open sort options: 'o' | Show help: '?'" (length? Let's count: ~110 chars) wraps to 2 lines. 110/80=1.375 => 2 lines. At 100 width, same text wraps to 2 lines as well (100*2=200, 110 fits in 2). At 120 width, wraps to 1 line (110<120). So simple char count wrapping (ceil(len/width)) gives: 80=>2, 100=>2, 120=>1. Matches!
        // For other footers, similar.
        // So use ceil(len/width).
        // But need to handle unicode? Footer is ascii, so len==width.
        let len = text.chars().count() as u16;
        if len == 0 { return 1; }
        ((len + width - 1) / width).max(1)
    }

