        // For now, if msgbox, any of o,O,Enter,Esc closes?
        if self.msgbox.is_some() {
            match key.code {
                KeyCode::Char('o') | KeyCode::Char('O') | KeyCode::Enter | KeyCode::Esc => {
                    self.msgbox = None;
                    return Ok(false);
                }
                _ => return Ok(false),
            }
        }
        if self.delete_confirm {
            match key.code {
                KeyCode::Char('y') | KeyCode::Char('Y') => {
                    self.delete_confirm = false;
                    self.do_delete();
                    return Ok(false);
                }
                KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                    self.delete_confirm = false;
                    return Ok(false);
                }
                _ => return Ok(false),
            }
        }
        if let Some(_) = self.create_dialog {
            return self.handle_create_key(key);
        }
        if self.show_help {
            return self.handle_help_key(key);
        }
        // TODO: other popups
        // Main keys
        match key.code {
            KeyCode::Char('q') => {
                // If in multi-select, leave multi? Actually q in multi leaves, not quit. Check multi_select.
                if self.multi_select {
                    self.multi_select = false;
                    self.multi_selected.clear();
                    return Ok(false);
                }
                // If focus Content and editor has unsaved changes? What happens on q with unsaved? Does it prompt? Or discard? Need to test.
                // For now, quit directly.
                self.save_state();
                return Ok(true);
            }
            KeyCode::Char('?') => {
                self.show_help = true;
                self.help_tab = 0;
                self.help_scroll = 0;
                return Ok(false);
            }
            KeyCode::Tab => {
                // Cycle focus forward? Also Ctrl-l?
                self.toggle_focus();
                return Ok(false);
            }
            KeyCode::BackTab => {
                self.toggle_focus();
                return Ok(false);
            }
            KeyCode::Down | KeyCode::Char('j') => {
                if self.focus == Focus::Journals && !self.multi_select {
                    if !self.view.is_empty() {
                        self.selected = (self.selected + 1).min(self.view.len() - 1);
                        self.sync_editor_to_selected();
                    }
                } else if self.multi_select {
                    if !self.view.is_empty() {
                        self.selected = (self.selected + 1).min(self.view.len() - 1);
                        self.sync_editor_to_selected();
                    }
                }
                return Ok(false);
            }
            KeyCode::Up | KeyCode::Char('k') => {
                if self.selected > 0 {
                    self.selected -= 1;
                    self.sync_editor_to_selected();
                }
                return Ok(false);
            }
            KeyCode::Char('n') => {
                if self.focus == Focus::Journals && !self.multi_select {
                    self.open_create(false);
                }
                return Ok(false);
            }
            KeyCode::Char('e') => {
                if self.focus == Focus::Journals && self.selected_entry().is_some() {
                    self.open_create(true);
                }
                return Ok(false);
            }
            KeyCode::Enter => {
                // If focus Journals, edit content (enter Edit mode, focus Content)? Or if focus Content Normal, enter Edit?
                // From earlier: Enter with journals focused goes to Content Edit. Enter with content Normal goes to Edit.
                // What about Enter with content Edit? Inserts newline? Handle in editor.
                if self.focus == Focus::Journals {
                    if self.selected_entry().is_some() {
                        self.focus = Focus::Content;
                        self.editor_mode = EditorMode::Edit;
                        // Cursor to end? Or start? Original after Enter, cursor at start? Need to check.
                        self.editor_cursor = 0;
                    }
                } else {
                    if self.editor_mode == EditorMode::Normal {
                        self.editor_mode = EditorMode::Edit;
                    } else if self.editor_mode == EditorMode::Edit {
                        // Insert newline at cursor
                        self.editor_insert('\n');
                    }
                }
                return Ok(false);
            }
            _ => {}
        }
        // Handle Ctrl combos
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            match key.code {
                KeyCode::Char('m') => {
                    // Same as Enter
                    if self.focus == Focus::Journals {
                        if self.selected_entry().is_some() {
                            self.focus = Focus::Content;
                            self.editor_mode = EditorMode::Edit;
                            self.editor_cursor = 0;
                        }
                    } else {
                        if self.editor_mode == EditorMode::Normal {
                            self.editor_mode = EditorMode::Edit;
                        } else if self.editor_mode == EditorMode::Edit {
                            self.editor_insert('\n');
                        }
                    }
                    return Ok(false);
                }
                KeyCode::Char('l') => {
                    self.toggle_focus();
                    return Ok(false);
                }
                KeyCode::Char('h') => {
                    self.toggle_focus();
                    return Ok(false);
                }
                _ => {}
            }
        }
        // Editor keys when focus Content
        if self.focus == Focus::Content {
            return self.handle_editor_key(key);
        }
        Ok(false)
    }

    fn toggle_focus(&mut self) {
        self.focus = match self.focus {
            Focus::Journals => {
                // When switching to Content, set editor to Normal? Or keep?
                self.editor_mode = EditorMode::Normal;
                Focus::Content
            }
            Focus::Content => Focus::Journals,
        };
    }

    fn handle_editor_key(&mut self, key: KeyEvent) -> Result<bool> {
        match self.editor_mode {
            EditorMode::Edit => {
                match key.code {
                    KeyCode::Esc => {
                        self.editor_mode = EditorMode::Normal;
                        return Ok(false);
                    }
                    KeyCode::Char(c) => {
                        if key.modifiers.contains(KeyModifiers::CONTROL) {
                            match c {
                                'c' => {
                                    self.editor_mode = EditorMode::Normal;
                                    return Ok(false);
                                }
                                '[' => {
                                    self.editor_mode = EditorMode::Normal;
                                    return Ok(false);
                                }
                                _ => {
                                    // Emacs bindings? For now ignore
                                    return Ok(false);
                                }
                            }
                        } else {
                            self.editor_insert(c);
                            return Ok(false);
                        }
                    }
                    KeyCode::Backspace => {
                        self.editor_backspace();
                        return Ok(false);
                    }
                    KeyCode::Delete => {
                        self.editor_delete();
                        return Ok(false);
                    }
                    KeyCode::Left => {
                        if self.editor_cursor > 0 { self.editor_cursor -= 1; }
                        return Ok(false);
                    }
                    KeyCode::Right => {
                        if self.editor_cursor < self.editor_buffer.chars().count() { self.editor_cursor += 1; }
                        return Ok(false);
                    }
                    _ => {}
                }
            }
            EditorMode::Normal => {
                // Vim bindings? For now handle s to save, etc. But s is global? Actually s in Normal should save? Let's handle global keys that work in Normal?
                // The main handle_key already handles q,?,Tab,j,k,n,e,Enter. For Normal, need to handle v (visual), s (save), etc.
                // But main handle_key returns early for those? We need to handle here.
                match key.code {
                    KeyCode::Char('s') => {
                        self.save_current_entry_content();
                        return Ok(false);
                    }
                    KeyCode::Char('v') => {
                        self.editor_mode = EditorMode::Visual;
                        return Ok(false);
                    }
                    KeyCode::Esc => {
                        // Back to Journals? Or stay? Original: Esc in Normal with Content focused? Does it go to Journals? Let's see: after Esc from Edit to Normal, focus stays Content. Pressing Esc again? Does it do anything? Possibly back to Journals? Need to test.
                        // For now, do nothing.
                        return Ok(false);
                    }
                    _ => {}
                }
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match key.code {
                        KeyCode::Char('s') => {
                            self.save_current_entry_content();
                            return Ok(false);
                        }
                        _ => {}
                    }
                }
            }
            EditorMode::Visual => {
                match key.code {
                    KeyCode::Esc => {
                        self.editor_mode = EditorMode::Normal;
                        return Ok(false);
                    }
                    KeyCode::Char('v') => {
                        self.editor_mode = EditorMode::Normal;
                        return Ok(false);
                    }
                    _ => {}
                }
            }
        }
        Ok(false)
    }

    fn editor_insert(&mut self, c: char) {
        let mut chars: Vec<char> = self.editor_buffer.chars().collect();
        if self.editor_cursor > chars.len() { self.editor_cursor = chars.len(); }
        chars.insert(self.editor_cursor, c);
        self.editor_buffer = chars.into_iter().collect();
        self.editor_cursor += 1;
    }
    fn editor_backspace(&mut self) {
        if self.editor_cursor > 0 {
            let mut chars: Vec<char> = self.editor_buffer.chars().collect();
            chars.remove(self.editor_cursor - 1);
            self.editor_buffer = chars.into_iter().collect();
            self.editor_cursor -= 1;
        }
    }
    fn editor_delete(&mut self) {
        let mut chars: Vec<char> = self.editor_buffer.chars().collect();
        if self.editor_cursor < chars.len() {
            chars.remove(self.editor_cursor);
            self.editor_buffer = chars.into_iter().collect();
        }
    }

    fn open_create(&mut self, is_edit: bool) {
        if is_edit {
            if let Some(e) = self.selected_entry() {
                let date_str = e.date.format("%d-%m-%Y").to_string();
                let prio_str = e.priority.map(|p| p.to_string()).unwrap_or_default();
                let tags_str = e.tags.join(", ");
                self.create_dialog = Some(CreateDialog {
                    is_edit: true,
                    edit_id: Some(e.id),
                    title: e.title.clone(),
                    title_cursor: e.title.chars().count(),
                    date: date_str,
                    date_cursor: 10,
                    priority: prio_str,
                    priority_cursor: prio_str.chars().count(),
                    tags: tags_str.clone(),
                    tags_cursor: tags_str.chars().count(),
                    focused: 0,
                    title_error: None,
                    date_error: None,
                    priority_error: None,
                });
            }
        } else {
            let today = chrono::Local::now().format("%d-%m-%Y").to_string();
            self.create_dialog = Some(CreateDialog {
                is_edit: false,
                edit_id: None,
                title: String::new(),
                title_cursor: 0,
                date: today,
                date_cursor: 10,
                priority: String::new(),
                priority_cursor: 0,
                tags: String::new(),
                tags_cursor: 0,
                focused: 0,
                title_error: None,
                date_error: None,
                priority_error: None,
            });
        }
    }

    fn handle_create_key(&mut self, key: KeyEvent) -> Result<bool> {
        // Handle Tab, Enter, Esc, and input
        let dlg = self.create_dialog.as_mut().unwrap();
        match key.code {
            KeyCode::Tab => {
                dlg.focused = (dlg.focused + 1) % 4;
                return Ok(false);
            }
            KeyCode::BackTab => {
                dlg.focused = (dlg.focused + 3) % 4;
                return Ok(false);
            }
            KeyCode::Esc => {
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    // Ctrl-c? Actually Esc with Ctrl? For Ctrl-c, code is Char('c') with Ctrl, not Esc. So plain Esc cancels.
                }
                self.create_dialog = None;
                return Ok(false);
            }
            KeyCode::Enter => {
                // Confirm
                let valid = self.validate_create_dialog();
                if valid {
                    self.confirm_create_dialog();
                    self.create_dialog = None;
                }
                return Ok(false);
            }
            _ => {}
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            match key.code {
                KeyCode::Char('m') => {
                    let valid = self.validate_create_dialog();
                    if valid {
                        self.confirm_create_dialog();
                        self.create_dialog = None;
                    }
                    return Ok(false);
                }
                KeyCode::Char('c') => {
                    self.create_dialog = None;
                    return Ok(false);
                }
                _ => return Ok(false),
            }
        }
        // Input for focused field
        match key.code {
            KeyCode::Char(c) => {
                // Ignore if Ctrl? Already handled.
                self.create_input(c);
            }
            KeyCode::Backspace => {
                self.create_backspace();
            }
            KeyCode::Delete => {
                self.create_delete();
            }
            KeyCode::Left => {
                self.create_move(-1);
            }
            KeyCode::Right => {
                self.create_move(1);
            }
            KeyCode::Home => {
                self.create_home();
            }
            KeyCode::End => {
                self.create_end();
            }
            _ => {}
        }
        Ok(false)
    }

    fn create_input(&mut self, c: char) {
        if let Some(dlg) = self.create_dialog.as_mut() {
            match dlg.focused {
                0 => {
                    let mut chars: Vec<char> = dlg.title.chars().collect();
                    if dlg.title_cursor > chars.len() { dlg.title_cursor = chars.len(); }
                    chars.insert(dlg.title_cursor, c);
                    dlg.title = chars.into_iter().collect();
                    dlg.title_cursor += 1;
                    dlg.title_error = None;
                }
                1 => {
                    let mut chars: Vec<char> = dlg.date.chars().collect();
                    if dlg.date_cursor > chars.len() { dlg.date_cursor = chars.len(); }
                    chars.insert(dlg.date_cursor, c);
                    dlg.date = chars.into_iter().collect();
                    dlg.date_cursor += 1;
                    dlg.date_error = None;
                }
                2 => {
                    let mut chars: Vec<char> = dlg.priority.chars().collect();
                    if dlg.priority_cursor > chars.len() { dlg.priority_cursor = chars.len(); }
                    chars.insert(dlg.priority_cursor, c);
                    dlg.priority = chars.into_iter().collect();
                    dlg.priority_cursor += 1;
                    dlg.priority_error = None;
                }
                3 => {
                    let mut chars: Vec<char> = dlg.tags.chars().collect();
                    if dlg.tags_cursor > chars.len() { dlg.tags_cursor = chars.len(); }
                    chars.insert(dlg.tags_cursor, c);
                    dlg.tags = chars.into_iter().collect();
                    dlg.tags_cursor += 1;
                }
                _ => {}
            }
        }
    }
    fn create_backspace(&mut self) {
        if let Some(dlg) = self.create_dialog.as_mut() {
            match dlg.focused {
                0 => if dlg.title_cursor > 0 {
                    let mut chars: Vec<char> = dlg.title.chars().collect();
                    chars.remove(dlg.title_cursor-1);
                    dlg.title = chars.into_iter().collect();
                    dlg.title_cursor -= 1;
                }
                1 => if dlg.date_cursor > 0 {
                    let mut chars: Vec<char> = dlg.date.chars().collect();
                    chars.remove(dlg.date_cursor-1);
                    dlg.date = chars.into_iter().collect();
                    dlg.date_cursor -= 1;
                }
                2 => if dlg.priority_cursor > 0 {
                    let mut chars: Vec<char> = dlg.priority.chars().collect();
                    chars.remove(dlg.priority_cursor-1);
                    dlg.priority = chars.into_iter().collect();
                    dlg.priority_cursor -= 1;
                }
                3 => if dlg.tags_cursor > 0 {
                    let mut chars: Vec<char> = dlg.tags.chars().collect();
                    chars.remove(dlg.tags_cursor-1);
                    dlg.tags = chars.into_iter().collect();
                    dlg.tags_cursor -= 1;
                }
                _ => {}
            }
        }
    }
    fn create_delete(&mut self) {
        if let Some(dlg) = self.create_dialog.as_mut() {
            match dlg.focused {
                0 => {
                    let mut chars: Vec<char> = dlg.title.chars().collect();
                    if dlg.title_cursor < chars.len() {
                        chars.remove(dlg.title_cursor);
                        dlg.title = chars.into_iter().collect();
                    }
                }
                1 => {
                    let mut chars: Vec<char> = dlg.date.chars().collect();
                    if dlg.date_cursor < chars.len() {
                        chars.remove(dlg.date_cursor);
                        dlg.date = chars.into_iter().collect();
                    }
                }
                2 => {
                    let mut chars: Vec<char> = dlg.priority.chars().collect();
                    if dlg.priority_cursor < chars.len() {
                        chars.remove(dlg.priority_cursor);
                        dlg.priority = chars.into_iter().collect();
                    }
                }
                3 => {
                    let mut chars: Vec<char> = dlg.tags.chars().collect();
                    if dlg.tags_cursor < chars.len() {
                        chars.remove(dlg.tags_cursor);
                        dlg.tags = chars.into_iter().collect();
                    }
                }
                _ => {}
            }
        }
    }
    fn create_move(&mut self, dir: i32) {
        if let Some(dlg) = self.create_dialog.as_mut() {
            match dlg.focused {
                0 => {
                    if dir < 0 && dlg.title_cursor > 0 { dlg.title_cursor -= 1; }
                    if dir > 0 && dlg.title_cursor < dlg.title.chars().count() { dlg.title_cursor += 1; }
                }
                1 => {
                    if dir < 0 && dlg.date_cursor > 0 { dlg.date_cursor -= 1; }
                    if dir > 0 && dlg.date_cursor < dlg.date.chars().count() { dlg.date_cursor += 1; }
                }
                2 => {
                    if dir < 0 && dlg.priority_cursor > 0 { dlg.priority_cursor -= 1; }
                    if dir > 0 && dlg.priority_cursor < dlg.priority.chars().count() { dlg.priority_cursor += 1; }
                }
                3 => {
                    if dir < 0 && dlg.tags_cursor > 0 { dlg.tags_cursor -= 1; }
                    if dir > 0 && dlg.tags_cursor < dlg.tags.chars().count() { dlg.tags_cursor += 1; }
                }
                _ => {}
            }
        }
    }
    fn create_home(&mut self) {
        if let Some(dlg) = self.create_dialog.as_mut() {
            match dlg.focused {
                0 => dlg.title_cursor = 0,
                1 => dlg.date_cursor = 0,
                2 => dlg.priority_cursor = 0,
                3 => dlg.tags_cursor = 0,
                _ => {}
            }
        }
    }
    fn create_end(&mut self) {
        if let Some(dlg) = self.create_dialog.as_mut() {
            match dlg.focused {
                0 => dlg.title_cursor = dlg.title.chars().count(),
                1 => dlg.date_cursor = dlg.date.chars().count(),
                2 => dlg.priority_cursor = dlg.priority.chars().count(),
                3 => dlg.tags_cursor = dlg.tags.chars().count(),
                _ => {}
            }
        }
    }

    fn validate_create_dialog(&mut self) -> bool {
        let mut ok = true;
        if let Some(dlg) = self.create_dialog.as_mut() {
            if dlg.title.trim().is_empty() {
                dlg.title_error = Some("Title can't be empty".to_string());
                ok = false;
            } else {
                dlg.title_error = None;
            }
            // Date: must be DD-MM-YYYY, valid date, only digits and '-'? Error "input contains invalid characters" if contains letters? Or "invalid date"? Need to infer.
            // For now: check if date matches DD-MM-YYYY and valid.
            if let Err(e) = parse_dialog_date(&dlg.date) {
                dlg.date_error = Some(e);
                ok = false;
            } else {
                dlg.date_error = None;
            }
            // Priority: empty or u32? Error? If invalid, show? What message? Need to test: type "abc" in priority, what error?
            if !dlg.priority.trim().is_empty() {
                if dlg.priority.trim().parse::<u32>().is_err() {
                    dlg.priority_error = Some("Invalid priority".to_string()); // Guess? Need to test actual message.
                    ok = false;
                } else {
                    dlg.priority_error = None;
                }
            } else {
                dlg.priority_error = None;
            }
        }
        ok
    }

    fn confirm_create_dialog(&mut self) {
        if let Some(dlg) = self.create_dialog.clone() {
            let date = parse_dialog_date(&dlg.date).unwrap();
            let priority = if dlg.priority.trim().is_empty() { None } else { dlg.priority.trim().parse::<u32>().ok() };
            let tags: Vec<String> = dlg.tags.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
            if dlg.is_edit {
                if let Some(id) = dlg.edit_id {
                    if let Some(entry) = self.entries.iter_mut().find(|e| e.id == id) {
                        entry.title = dlg.title.clone();
                        entry.date = date;
                        entry.priority = priority;
                        entry.tags = tags.clone();
                        // Save
                        match self.settings.backend_type {
                            BackendType::Json => {
                                let p = self.settings.json_backend.file_path.clone();
                                let _ = crate::backend::save_json(&p, &self.entries);
                            }
                            BackendType::Sqlite => {
                                let p = self.settings.sqlite_backend.file_path.clone();
                                let e2 = entry.clone();
                                let _ = crate::backend::update_sqlite(&p, &e2);
                            }
                        }
                    }
                }
            } else {
                match self.settings.backend_type {
                    BackendType::Json => {
                        let nid = if self.entries.is_empty() { 0 } else { self.entries.iter().map(|e| e.id).max().unwrap() + 1 };
                        let new_entry = Entry { id: nid, date, title: dlg.title.clone(), content: String::new(), tags, priority };
                        self.entries.push(new_entry);
                        let p = self.settings.json_backend.file_path.clone();
                        let _ = crate::backend::save_json(&p, &self.entries);
                    }
                    BackendType::Sqlite => {
                        let new_entry = Entry { id: 0, date, title: dlg.title.clone(), content: String::new(), tags, priority };
                        let p = self.settings.sqlite_backend.file_path.clone();
                        if let Ok(nid) = crate::backend::insert_sqlite(&p, &new_entry) {
                            let mut e2 = new_entry.clone();
                            e2.id = nid;
                            self.entries.push(e2);
                        }
                    }
                }
            }
            self.rebuild_view();
            // Select new/edited entry? For create, select new entry (find by id? Or by title?). Original after create selects new entry? In our earlier test, after create, selected was new entry (only one). With multiple, where does selection go? Likely to new entry (by finding its view index). Let's select by id.
            // For edit, keep selection? Or move to edited? Keep.
            if !dlg.is_edit {
                // Find new entry's view index (last inserted id)
                // For JSON, nid is max+1, for SQLite, need to find max id? Actually we pushed, so last entry's id is new.
                if let Some(last) = self.entries.last() {
                    let nid = last.id;
                    // Find view index with that id
                    for (vi, &ei) in self.view.iter().enumerate() {
                        if self.entries[ei].id == nid {
                            self.selected = vi;
                            break;
                        }
                    }
                }
            }
            self.sync_editor_to_selected();
        }
    }

    fn do_delete(&mut self) {
        if let Some(&idx) = self.view.get(self.selected) {
            let id = self.entries[idx].id;
            match self.settings.backend_type {
                BackendType::Json => {
                    self.entries.retain(|e| e.id != id);
                    let p = self.settings.json_backend.file_path.clone();
                    let _ = crate::backend::save_json(&p, &self.entries);
                }
                BackendType::Sqlite => {
                    let p = self.settings.sqlite_backend.file_path.clone();
                    let _ = crate::backend::delete_sqlite(&p, id);
                    self.entries.retain(|e| e.id != id);
                }
            }
            self.rebuild_view();
            self.sync_editor_to_selected();
        }
    }

    fn handle_help_key(&mut self, key: KeyEvent) -> Result<bool> {
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('?') => {
                self.show_help = false;
                return Ok(false);
            }
            KeyCode::Tab => {
                self.help_tab = (self.help_tab + 1) % 3;
                self.help_scroll = 0;
                return Ok(false);
            }
            KeyCode::BackTab => {
                self.help_tab = (self.help_tab + 2) % 3;
                self.help_scroll = 0;
                return Ok(false);
            }
            KeyCode::Down | KeyCode::Char('j') => {
                self.help_scroll = self.help_scroll.saturating_add(1);
                return Ok(false);
            }
            KeyCode::Up | KeyCode::Char('k') => {
                self.help_scroll = self.help_scroll.saturating_sub(1);
                return Ok(false);
            }
            KeyCode::PageDown => {
                // In original, PageDown switches tabs? Actually earlier we saw PageDown switched to Editor tab. Hmm, maybe PageDown/Up switch tabs? Or scroll?
                // For now, treat as tab switch? Let's check: earlier, pressing PageDown 10 times switched to Editor tab. That suggests PageDown switches tabs, not scrolls. But Down scrolls.
                // Actually our earlier test: after help, pressing Page_Down 10 times resulted in Editor tab (not scrolled Global). So PageDown switches tabs.
                // Let's implement: PageDown -> next tab, PageUp -> prev tab?
                self.help_tab = (self.help_tab + 1) % 3;
                self.help_scroll = 0;
                return Ok(false);
            }
            KeyCode::PageUp => {
                self.help_tab = (self.help_tab + 2) % 3;
                self.help_scroll = 0;
                return Ok(false);
            }
            _ => {}
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            // Ctrl-c closes? Original: Esc, Ctrl-c, etc. in help? Actually help says q,?,Esc? Let's just handle Ctrl-c as close.
            if let KeyCode::Char('c') = key.code {
                self.show_help = false;
                return Ok(false);
            }
        }
        Ok(false)
    }
}

fn parse_dialog_date(s: &str) -> Result<DateTime<Utc>, String> {
    let trimmed = s.trim();
    // Check invalid characters: only digits and '-' allowed? If contains letters, error "input contains invalid characters"
    if trimmed.chars().any(|c| !(c.is_ascii_digit() || c == '-')) {
        return Err("input contains invalid characters".to_string());
    }
    // Parse DD-MM-YYYY
    let parts: Vec<&str> = trimmed.split('-').collect();
    if parts.len() != 3 {
        return Err("Invalid date format".to_string()); // Guess? Need to test actual message for "13/09/2026" or "13-09" etc.
    }
    let day: u32 = parts[0].parse().map_err(|_| "Invalid date".to_string())?;
    let month: u32 = parts[1].parse().map_err(|_| "Invalid date".to_string())?;
    let year: i32 = parts[2].parse().map_err(|_| "Invalid date".to_string())?;
    use chrono::{NaiveDate, TimeZone};
    let naive = NaiveDate::from_ymd_opt(year, month, day).ok_or("Invalid date".to_string())?;
    let dt = naive.and_hms_opt(0,0,0).unwrap();
    Ok(Utc.from_utc_datetime(&dt))
}
