fn run_loop(terminal: &mut Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>, opts: TuiOptions) -> Result<()> {
    let mut app = App::new(opts)?;
    // Handle import/assign before loop? They should be done with popups if errors, else directly.
    app.handle_startup_ops()?;
    loop {
        terminal.draw(|f| app.render(f)).map_err(|e| anyhow::anyhow!("{}", e))?;
        if event::poll(std::time::Duration::from_millis(100)).map_err(|e| anyhow::anyhow!("{}", e))? {
            if let Event::Key(key) = event::read().map_err(|e| anyhow::anyhow!("{}", e))? {
                if app.handle_key(key)? {
                    break;
                }
            }
        }
    }
    Ok(())
}

impl App {
    fn new(opts: TuiOptions) -> Result<Self> {
        let settings = opts.settings.clone();
        // Load state.json for sorter/fullscreen
        let state_path = settings.app_state_dir.join("state.json");
        let (mut criteria, mut order, mut full_screen) = (vec!["Date".to_string(),"Priority".to_string()], "Descending".to_string(), false);
        if state_path.exists() {
            if let Ok(content) = std::fs::read_to_string(&state_path) {
                if let Ok(v) = serde_json::from_str::<serde_json::Value>(&content) {
                    if let Some(sorter) = v.get("sorter") {
                        if let Some(c) = sorter.get("criteria").and_then(|c| c.as_array()) {
                            criteria = c.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
                            if criteria.is_empty() {
                                criteria = vec!["Date".to_string(),"Priority".to_string()];
                            }
                        }
                        if let Some(o) = sorter.get("order").and_then(|o| o.as_str()) {
                            order = o.to_string();
                        }
                    }
                    if let Some(fs) = v.get("full_screen").and_then(|f| f.as_bool()) {
                        full_screen = fs;
                    }
                }
            }
        } else {
            // Create state dir and file with defaults
            if let Some(parent) = state_path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            let default_state = serde_json::json!({"sorter":{"criteria":["Date","Priority"],"order":"Descending"},"full_screen":false});
            let _ = std::fs::write(&state_path, serde_json::to_string_pretty(&default_state).unwrap_or_default());
        }
        // Load entries
        let backend_path = match settings.backend_type {
            BackendType::Json => settings.json_backend.file_path.clone(),
            BackendType::Sqlite => settings.sqlite_backend.file_path.clone(),
        };
        // Ensure parent dirs exist
        if let Some(parent) = backend_path.parent() {
            if !parent.as_os_str().is_empty() {
                let _ = std::fs::create_dir_all(parent);
            }
        }
        let mut entries = Vec::new();
        let mut load_error = None;
        match settings.backend_type {
            BackendType::Json => {
                match crate::backend::load_json(&backend_path) {
                    Ok(e) => entries = e,
                    Err(err) => {
                        let msg = format!("{}", err);
                        // Check if it's parse error vs io error
                        // load_json returns "Error while parsing entries json data" for parse, or io error string for io
                        load_error = Some(msg);
                        entries = Vec::new();
                    }
                }
            }
            BackendType::Sqlite => {
                match crate::backend::load_sqlite(&backend_path) {
                    Ok(e) => entries = e,
                    Err(err) => {
                        // For sqlite, fatal error with sqlx formatting
                        // Try to format as sqlx: need code and message
                        // Our backend returns generic anyhow with sqlite errmsg, not code.
                        // For now, return error directly (will exit with Error: ...)
                        // But need to match sqlx format: "error returned from database: (code: X) msg" with cause
                        // Let's try to parse code from message? Our backend doesn't provide code.
                        // As fallback, return error as is (may not match exactly, but close)
                        // To match exactly for "file is not a database" (code 26) and "unable to open" (code 14),
                        // we need to detect and format.
                        let msg = format!("{}", err);
                        // Detect code by message substring
                        let (code, m) = if msg.contains("file is not a database") {
                            (26, "file is not a database")
                        } else if msg.contains("unable to open") {
                            (14, "unable to open database file")
                        } else {
                            // Generic: try to get code? Default to 1?
                            (1, msg.as_str())
                        };
                        let err2 = anyhow::anyhow!("(code: {}) {}", code, m).context(format!("error returned from database: (code: {}) {}", code, m));
                        return Err(err2);
                    }
                }
            }
        }
        let mut app = Self {
            settings,
            entries,
            view: Vec::new(),
            selected: 0,
            focus: Focus::Journals,
            editor_mode: EditorMode::Normal,
            editor_buffer: String::new(),
            editor_cursor: 0,
            editor_original: String::new(),
            show_help: false,
            help_tab: 0,
            help_scroll: 0,
            create_dialog: None,
            filter_popup: None,
            sort_popup: None,
            fuzzy_popup: None,
            export_popup: None,
            delete_confirm: false,
            msgbox: None,
            multi_select: false,
            multi_selected: std::collections::HashSet::new(),
            full_screen,
            sorter_criteria: criteria,
            sorter_order: order,
            filter: FilterState { title: String::new(), content: String::new(), priority: String::new(), selected_tags: std::collections::HashSet::new(), matching_all: true, active: false },
            load_error,
            import_path: opts.import_path.clone(),
            assign_priority: opts.assign_priority,
            list_offset: 0,
        };
        app.rebuild_view();
        // If load_error, show msgbox
        if let Some(err) = app.load_error.clone() {
            // For json parse error, show "Error while parsing entries json data" popup
            // For io error (permission denied), show that message
            app.msgbox = Some(MsgBox { kind: "Error".to_string(), title: "Error".to_string(), lines: vec![err] });
        }
        // Init editor buffer to selected entry content
        app.sync_editor_to_selected();
        Ok(app)
    }

    fn handle_startup_ops(&mut self) -> Result<()> {
        // Import
        if let Some(ip) = self.import_path.clone() {
            self.do_import(&ip);
            // Clear to avoid re-import on reload?
            self.import_path = None;
        }
        // Assign
        if let Some(prio) = self.assign_priority {
            self.do_assign(prio);
            self.assign_priority = None;
        }
        // Save state? Already ensured
        Ok(())
    }

    fn do_import(&mut self, path: &PathBuf) {
        // Check exists
        if !path.exists() {
            self.msgbox = Some(MsgBox { kind: "Error".to_string(), title: "Error".to_string(), lines: vec![format!("Import file doesn't exist: path {}", path.display())] });
            return;
        }
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                self.msgbox = Some(MsgBox { kind: "Error".to_string(), title: "Error".to_string(), lines: vec![format!("Error while parsing import file. Error: {}", e)] });
                return;
            }
        };
        let tf: Result<TransferFile, _> = serde_json::from_str(&content);
        match tf {
            Ok(t) => {
                // Import each entry
                for te in t.entries {
                    let new_entry = Entry {
                        id: 0, // will assign
                        date: te.date,
                        title: te.title,
                        content: te.content,
                        tags: te.tags,
                        priority: te.priority,
                    };
                    match self.settings.backend_type {
                        BackendType::Json => {
                            let new_id = self.entries.iter().map(|e| e.id).max().unwrap_or(0).checked_add(1).unwrap_or(0);
                            // If empty, id 0? Actually for empty, max fails, use 0. For non-empty with max 0, new is 1. Good.
                            // But need to handle empty case: max None => 0? Our code: max().unwrap_or(0) gives 0 for empty, then +1 gives 1, wrong (should be 0 for first). Fix:
                            let nid = if self.entries.is_empty() { 0 } else { self.entries.iter().map(|e| e.id).max().unwrap() + 1 };
                            let mut e2 = new_entry.clone();
                            e2.id = nid;
                            self.entries.push(e2);
                        }
                        BackendType::Sqlite => {
                            let backend_path = self.settings.sqlite_backend.file_path.clone();
                            // insert via backend, get new id
                            match crate::backend::insert_sqlite(&backend_path, &new_entry) {
                                Ok(nid) => {
                                    let mut e2 = new_entry.clone();
                                    e2.id = nid;
                                    self.entries.push(e2);
                                }
                                Err(e) => {
                                    self.msgbox = Some(MsgBox { kind: "Error".to_string(), title: "Error".to_string(), lines: vec![format!("{}", e)] });
                                    return;
                                }
                            }
                        }
                    }
                }
                // For JSON, save after import (if any entries imported)
                if self.settings.backend_type == BackendType::Json {
                    if !t.entries.is_empty() {
                        let backend_path = self.settings.json_backend.file_path.clone();
                        let _ = crate::backend::save_json(&backend_path, &self.entries);
                    }
                }
                self.rebuild_view();
                self.sync_editor_to_selected();
            }
            Err(e) => {
                self.msgbox = Some(MsgBox { kind: "Error".to_string(), title: "Error".to_string(), lines: vec![format!("Error while parsing import file. Error: {}", e)] });
            }
        }
    }

    fn do_assign(&mut self, prio: u32) {
        let mut changed = false;
        for e in self.entries.iter_mut() {
            if e.priority.is_none() {
                e.priority = Some(prio);
                changed = true;
            }
        }
        if changed {
            match self.settings.backend_type {
                BackendType::Json => {
                    let backend_path = self.settings.json_backend.file_path.clone();
                    let _ = crate::backend::save_json(&backend_path, &self.entries);
                }
                BackendType::Sqlite => {
                    let backend_path = self.settings.sqlite_backend.file_path.clone();
                    let _ = crate::backend::assign_priority_sqlite(&backend_path, prio);
                    // Also need to reload? Already updated in memory, ok.
                }
            }
        }
        self.rebuild_view();
        self.sync_editor_to_selected();
    }

    fn rebuild_view(&mut self) {
        // Apply filter, then sort
        let mut indices: Vec<usize> = (0..self.entries.len()).collect();
        // Filter
        if self.filter.active {
            indices.retain(|&i| self.matches_filter(&self.entries[i]));
        }
        // Sort
        let criteria = self.sorter_criteria.clone();
        let order = self.sorter_order.clone();
        indices.sort_by(|&a, &b| {
            let ea = &self.entries[a];
            let eb = &self.entries[b];
            for crit in &criteria {
                let ord = match crit.as_str() {
                    "Date" => ea.date.cmp(&eb.date),
                    "Priority" => match (&ea.priority, &eb.priority) {
                        (None, None) => std::cmp::Ordering::Equal,
                        (None, Some(_)) => std::cmp::Ordering::Less,
                        (Some(_), None) => std::cmp::Ordering::Greater,
                        (Some(x), Some(y)) => x.cmp(y),
                    },
                    "Title" => ea.title.cmp(&eb.title),
                    _ => std::cmp::Ordering::Equal,
                };
                if ord != std::cmp::Ordering::Equal {
                    if order == "Descending" {
                        return ord.reverse();
                    } else {
                        return ord;
                    }
                }
            }
            // Tie-breaker by id? Original likely stable? Use id.
            ea.id.cmp(&eb.id)
        });
        self.view = indices;
        if self.selected >= self.view.len() && !self.view.is_empty() {
            self.selected = self.view.len() - 1;
        }
        if self.view.is_empty() {
            self.selected = 0;
        }
    }

    fn matches_filter(&self, e: &Entry) -> bool {
        // Title, content, priority, tags
        // If filter has no criteria? Then all pass? Or if matching_all vs any?
        let mut checks: Vec<bool> = Vec::new();
        if !self.filter.title.is_empty() {
            checks.push(e.title.to_lowercase().contains(&self.filter.title.to_lowercase()));
        }
        if !self.filter.content.is_empty() {
            checks.push(e.content.to_lowercase().contains(&self.filter.content.to_lowercase()));
        }
        if !self.filter.priority.is_empty() {
            // Priority filter: how does it work? Possibly exact match? Or contains? Let's assume exact match of priority number string?
            // If entry priority None, then false unless filter is empty? But filter not empty here.
            if let Some(p) = e.priority {
                checks.push(p.to_string() == self.filter.priority);
            } else {
                checks.push(false);
            }
        }
        if !self.filter.selected_tags.is_empty() {
            // If NO_TAGS selected? Tags list includes "NO_TAGS (Entries with no tags)"? How to handle?
            // For now: check if entry has any of selected tags, or if NO_TAGS selected and entry has no tags.
            let mut tag_match = false;
            for t in &self.filter.selected_tags {
                if t == "NO_TAGS" {
                    if e.tags.is_empty() {
                        tag_match = true;
                        break;
                    }
                } else if e.tags.contains(t) {
                    tag_match = true;
                    break;
                }
            }
            checks.push(tag_match);
        }
        if checks.is_empty() {
            return true;
        }
        if self.filter.matching_all {
            checks.iter().all(|&x| x)
        } else {
            checks.iter().any(|&x| x)
        }
    }

    fn sync_editor_to_selected(&mut self) {
        if let Some(&idx) = self.view.get(self.selected) {
            let content = self.entries[idx].content.clone();
            self.editor_buffer = content.clone();
            self.editor_original = content;
            self.editor_cursor = 0;
            self.editor_mode = EditorMode::Normal;
        } else {
            self.editor_buffer.clear();
            self.editor_original.clear();
            self.editor_cursor = 0;
            self.editor_mode = EditorMode::Normal;
        }
    }

    fn selected_entry(&self) -> Option<&Entry> {
        self.view.get(self.selected).map(|&i| &self.entries[i])
    }

    fn selected_entry_mut(&mut self) -> Option<&mut Entry> {
        if let Some(&i) = self.view.get(self.selected) {
            self.entries.get_mut(i)
        } else {
            None
        }
    }

    fn save_state(&self) {
        let state_path = self.settings.app_state_dir.join("state.json");
        if let Some(parent) = state_path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let v = serde_json::json!({"sorter":{"criteria": self.sorter_criteria, "order": self.sorter_order},"full_screen": self.full_screen});
        let _ = std::fs::write(&state_path, serde_json::to_string_pretty(&v).unwrap_or_default());
    }

    fn save_current_entry_content(&mut self) {
        let new_content = self.editor_buffer.clone();
        if let Some(&idx) = self.view.get(self.selected) {
            let entry_id = self.entries[idx].id;
            self.entries[idx].content = new_content.clone();
            // Save to backend
            match self.settings.backend_type {
                BackendType::Json => {
                    let p = self.settings.json_backend.file_path.clone();
                    let _ = crate::backend::save_json(&p, &self.entries);
                }
                BackendType::Sqlite => {
                    let p = self.settings.sqlite_backend.file_path.clone();
                    let e = self.entries[idx].clone();
                    let _ = crate::backend::update_sqlite(&p, &e);
                }
            }
            self.editor_original = new_content;
        }
    }

    fn render(&mut self, f: &mut Frame) {
        let area = f.area();
        // Footer text
        let footer_text = self.footer_text();
        // Calculate footer height by wrapping? Simple: if footer len > width, 2 lines else 1? But need exact wrapping as ratatui Paragraph with Wrap.
        // For now, compute by naive: if footer_text.len() > area.width as usize, then 2 else 1? But footer may wrap to more than 2? At narrow widths, could be 3? Original footer for journals at 80 width wraps to 2, at very narrow (e.g., 40) might wrap to 3-4. We need to handle generally.
        // Use textwrap? Simple: split by width.
        let footer_height = self.calc_footer_height(area.width, &footer_text);
        let main_height = area.height.saturating_sub(footer_height);
        let vertical = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(main_height), Constraint::Length(footer_height)]).split(area);
        let main_area = vertical[0];
        let footer_area = vertical[1];
        // Horizontal split 30/70 or fullscreen?
        if self.full_screen {
            // Show only focused pane fullscreen? Which pane? If focus Journals, show journals fullscreen, else content fullscreen?
            // From earlier, Ctrl-f with journals focused showed journals fullscreen (header "Journals" full width). Need to handle both.
            match self.focus {
                Focus::Journals => {
                    self.render_journals(f, main_area);
                }
                Focus::Content => {
                    self.render_content(f, main_area);
                }
            }
        } else {
            let horizontal = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(30), Constraint::Percentage(70)]).split(main_area);
            self.render_journals(f, horizontal[0]);
            self.render_content(f, horizontal[1]);
        }
        // Footer
        let footer = Paragraph::new(footer_text).wrap(Wrap { trim: false });
        f.render_widget(footer, footer_area);
        // Popups
        if self.show_help {
            self.render_help(f, area);
        }
        if self.create_dialog.is_some() {
            self.render_create_dialog(f, area);
        }
        if self.filter_popup.is_some() {
            self.render_filter(f, area);
        }
        if self.sort_popup.is_some() {
            self.render_sort(f, area);
        }
        if self.fuzzy_popup.is_some() {
            self.render_fuzzy(f, area);
        }
        if self.export_popup.is_some() {
            self.render_export(f, area);
        }
        if self.delete_confirm {
            self.render_delete_confirm(f, area);
        }
        if self.msgbox.is_some() {
            self.render_msgbox(f, area);
        }
    }

    fn calc_footer_height(&self, width: u16, text: &str) -> u16 {
        if width == 0 { return 1; }
        // Simulate ratatui Paragraph wrap: words wrap? Or char wrap? Ratatui Wrap with trim false wraps at width, breaking words? Actually it wraps by words? Need to check.
        // For footer, text contains " | " separators, no newlines. Wrapping is by width, breaking at spaces? Let's implement simple: split into words? Or just char count?
        // Observed: at 80 width, footer "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open sort options: 'o' | Show help: '?'" (length? Let's count: ~110 chars) wraps to 2 lines. 110/80=1.375 => 2 lines. At 100 width, same text wraps to 2 lines as well (100*2=200, 110 fits in 2). At 120 width, wraps to 1 line (110<120). So simple char count wrapping (ceil(len/width)) gives: 80=>2, 100=>2, 120=>1. Matches!
        // For other footers, similar.
        // So use ceil(len/width).
        // But need to handle unicode? Footer is ascii, so len==width.
        let len = text.chars().count() as u16;
        if len == 0 { return 1; }
        ((len + width - 1) / width).max(1)
    }

