            // For now, just render all with Paragraph and scroll?
            // Find start line to show selected?
            // Let's compute line index for selected
            let mut line_idx = 0;
            let mut sel_line = 0;
            for (view_idx, &entry_idx) in self.view.iter().enumerate() {
                if view_idx == self.selected {
                    sel_line = line_idx;
