                }
            }
            // Adjust list_offset to keep selected visible? Inner height
            let h = inner.height as usize;
            if sel_line < self.list_offset {
                self.list_offset = sel_line;
            } else if sel_line >= self.list_offset + h {
                self.list_offset = sel_line - h + 1;
            }
            // Also need to handle that selected entry may span multiple lines, ensure all visible? For simplicity, just ensure title visible.
            let visible: Vec<Line> = items.into_iter().skip(self.list_offset).take(h).collect();
