            // Handle day "00"? For day 05, trim gives "5", good. For day 10, "10", good. For month 09, "9", good. For day "00"? Not possible.
            // But trim "0" from "00"? Not needed. Also need to handle "0" itself? If day is "0"? Not possible (1-31). For month, 1-12. So safe. But what about "00"? Not.
            // Edge: if trim gives empty (for "00"), use "0"? Not needed.
        } else {
            None
        };
        // Fix empty after trim: if day is "08", trim gives "8", good. If day is "00"? Not.
        // Actually trim_start_matches('0') on "08" gives "8", on "10" gives "10", on "00" gives "", but day never 00.
        // For safety, if empty, use "0".
        let date_part = date_part.map(|s| {
            // s is like "13,9,2026"? Wait we formatted with trim per part, but our format above does trim per format? Actually we did format with three parts, each trimmed. Good.
            // But need to handle empty: e.g., day "08" -> "8", month "09" -> "9", good.
            s
        });
        // Better: compute day, month, year as numbers
        // Let's recompute correctly:
        let day = e.date.format("%d").to_string();
        let month = e.date.format("%m").to_string();
        let year = e.date.format("%Y").to_string();
        let day_n = day.trim_start_matches('0');
        let day_s = if day_n.is_empty() { "0" } else { day_n };
        let month_n = month.trim_start_matches('0');
