    fn handle_editor_key(&mut self, key: KeyEvent) -> Result<bool> {
        match self.editor_mode {
            EditorMode::Edit => {
                match key.code {
                    KeyCode::Esc => {
                        self.editor_mode = EditorMode::Normal;
                        return Ok(false);
                    }
                    KeyCode::Char(c) => {
                        if key.modifiers.contains(KeyModifiers::CONTROL) {
                            match c {
                                'c' => {
                                    self.editor_mode = EditorMode::Normal;
                                    return Ok(false);
                                }
                                '[' => {
                                    self.editor_mode = EditorMode::Normal;
                                    return Ok(false);
                                }
                                _ => {
                                    // Emacs bindings? For now ignore
                                    return Ok(false);
                                }
                            }
                        } else {
                            self.editor_insert(c);
                            return Ok(false);
                        }
                    }
                    KeyCode::Backspace => {
                        self.editor_backspace();
                        return Ok(false);
                    }
                    KeyCode::Delete => {
                        self.editor_delete();
                        return Ok(false);
                    }
                    KeyCode::Left => {
                        if self.editor_cursor > 0 { self.editor_cursor -= 1; }
                        return Ok(false);
                    }
                    KeyCode::Right => {
                        if self.editor_cursor < self.editor_buffer.chars().count() { self.editor_cursor += 1; }
                        return Ok(false);
                    }
                    _ => {}
                }
            }
            EditorMode::Normal => {
                // Vim bindings? For now handle s to save, etc. But s is global? Actually s in Normal should save? Let's handle global keys that work in Normal?
                // The main handle_key already handles q,?,Tab,j,k,n,e,Enter. For Normal, need to handle v (visual), s (save), etc.
                // But main handle_key returns early for those? We need to handle here.
                match key.code {
                    KeyCode::Char('s') => {
                        self.save_current_entry_content();
                        return Ok(false);
                    }
                    KeyCode::Char('v') => {
                        self.editor_mode = EditorMode::Visual;
                        return Ok(false);
                    }
                    KeyCode::Esc => {
                        // Back to Journals? Or stay? Original: Esc in Normal with Content focused? Does it go to Journals? Let's see: after Esc from Edit to Normal, focus stays Content. Pressing Esc again? Does it do anything? Possibly back to Journals? Need to test.
                        // For now, do nothing.
                        return Ok(false);
                    }
                    _ => {}
                }
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match key.code {
                        KeyCode::Char('s') => {
                            self.save_current_entry_content();
                            return Ok(false);
                        }
                        _ => {}
                    }
                }
            }
            EditorMode::Visual => {
                match key.code {
                    KeyCode::Esc => {
                        self.editor_mode = EditorMode::Normal;
                        return Ok(false);
                    }
                    KeyCode::Char('v') => {
                        self.editor_mode = EditorMode::Normal;
                        return Ok(false);
                    }
                    _ => {}
                }
            }
        }
        Ok(false)
    }

    fn editor_insert(&mut self, c: char) {
        let mut chars: Vec<char> = self.editor_buffer.chars().collect();
        if self.editor_cursor > chars.len() { self.editor_cursor = chars.len(); }
        chars.insert(self.editor_cursor, c);
        self.editor_buffer = chars.into_iter().collect();
        self.editor_cursor += 1;
    }
    fn editor_backspace(&mut self) {
        if self.editor_cursor > 0 {
            let mut chars: Vec<char> = self.editor_buffer.chars().collect();
            chars.remove(self.editor_cursor - 1);
            self.editor_buffer = chars.into_iter().collect();
            self.editor_cursor -= 1;
        }
    }
    fn editor_delete(&mut self) {
        let mut chars: Vec<char> = self.editor_buffer.chars().collect();
        if self.editor_cursor < chars.len() {
            chars.remove(self.editor_cursor);
            self.editor_buffer = chars.into_iter().collect();
        }
    }

