    fn handle_create_key(&mut self, key: KeyEvent) -> Result<bool> {
        // Handle Tab, Enter, Esc, and input
        let dlg = self.create_dialog.as_mut().unwrap();
        match key.code {
            KeyCode::Tab => {
                dlg.focused = (dlg.focused + 1) % 4;
                return Ok(false);
            }
            KeyCode::BackTab => {
                dlg.focused = (dlg.focused + 3) % 4;
                return Ok(false);
            }
            KeyCode::Esc => {
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    // Ctrl-c? Actually Esc with Ctrl? For Ctrl-c, code is Char('c') with Ctrl, not Esc. So plain Esc cancels.
                }
                self.create_dialog = None;
                return Ok(false);
            }
            KeyCode::Enter => {
                // Confirm
                let valid = self.validate_create_dialog();
                if valid {
                    self.confirm_create_dialog();
                    self.create_dialog = None;
                }
                return Ok(false);
            }
            _ => {}
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            match key.code {
                KeyCode::Char('m') => {
                    let valid = self.validate_create_dialog();
                    if valid {
                        self.confirm_create_dialog();
                        self.create_dialog = None;
                    }
                    return Ok(false);
                }
                KeyCode::Char('c') => {
                    self.create_dialog = None;
                    return Ok(false);
                }
                _ => return Ok(false),
            }
        }
        // Input for focused field
        match key.code {
            KeyCode::Char(c) => {
                // Ignore if Ctrl? Already handled.
                self.create_input(c);
            }
            KeyCode::Backspace => {
                self.create_backspace();
            }
            KeyCode::Delete => {
                self.create_delete();
            }
            KeyCode::Left => {
                self.create_move(-1);
            }
            KeyCode::Right => {
                self.create_move(1);
            }
            KeyCode::Home => {
                self.create_home();
            }
            KeyCode::End => {
                self.create_end();
            }
            _ => {}
        }
        Ok(false)
