                        let nid = if self.entries.is_empty() { 0 } else { self.entries.iter().map(|e| e.id).max().unwrap() + 1 };
                        let new_entry = Entry { id: nid, date, title: dlg.title.clone(), content: String::new(), tags, priority };
                        self.entries.push(new_entry);
                        let p = self.settings.json_backend.file_path.clone();
                        let _ = crate::backend::save_json(&p, &self.entries);
                    }
                    BackendType::Sqlite => {
                        let new_entry = Entry { id: 0, date, title: dlg.title.clone(), content: String::new(), tags, priority };
                        let p = self.settings.sqlite_backend.file_path.clone();
                        if let Ok(nid) = crate::backend::insert_sqlite(&p, &new_entry) {
